package de.funke.app.ui.challenge

import kotlin.math.PI
import kotlin.math.pow

/*
 * Physik-Ausbau (seit 13.2), Teil 8: Aufgaben mit ganz neuen Situationen in allen Gebieten, viele davon als
 * Denkfragen ohne Rechnung. Anregungen (nicht wörtlich): OpenStax University Physics (CC BY 4.0) und
 * Halliday/Resnick (nur Ideen). Alle Texte selbst geschrieben.
 */

private val E = Difficulty.Easy
private val M = Difficulty.Medium
private val H = Difficulty.Hard

object PhysNew8 {
    val all: List<TaskDef> get() = tasks

    private val tasks = listOf(
        // ------------------------------------------------ Bewegung
        lab("phy.vtflaeche", Topic.Motion, M, 0.5f) {
            val v = pick(20.0, 15.0, 25.0); val t1 = pick(10.0, 8.0); val t2 = pick(20.0, 30.0); val t3 = pick(5.0, 4.0)
            val s = v * t1 / 2 + v * t2 + v * t3 / 2
            task(
                question = l("Ein Fahrtenschreiber zeichnet die Geschwindigkeit eines Busses auf: In ${n(t1, 0)} s gleichmäßig von 0 auf ${n(v, 0)} m/s, dann ${n(t2, 0)} s lang konstant, dann in ${n(t3, 0)} s gleichmäßig bis zum Stillstand. Welche Strecke hat der Bus zurückgelegt?", "A tachograph records a bus's speed: from 0 to ${n(v, 0)} m/s evenly in ${n(t1, 0)} s, then constant for ${n(t2, 0)} s, then evenly down to a stop in ${n(t3, 0)} s. How far has the bus travelled?"),
                steps = listOf(num(l("Strecke in m", "Distance in m"), s, "m", rel = 0.01, done = """§s = ${m(s, 0)}\ \text{m}§""",
                    hints = listOf(l("Kernidee: Im Geschwindigkeit-Zeit-Diagramm ist die Strecke die Fläche unter der Kurve. Hier ist das ein Trapez aus zwei Dreiecken und einem Rechteck.", "Key idea: in a speed–time graph the distance is the area under the curve. Here that's a trapezium made of two triangles and a rectangle."), """§s = \tfrac{1}{2} v t_1 + v t_2 + \tfrac{1}{2} v t_3§"""))),
                solution = listOf("""§s = ${m(v * t1 / 2, 0)} + ${m(v * t2, 0)} + ${m(v * t3 / 2, 0)} = ${m(s, 0)}\ \text{m}§"""),
                background = l("Fläche unter der Geschwindigkeitskurve gleich Strecke: Das ist schon die Grundidee der Integralrechnung. Beim Beschleunigen und Bremsen fährt der Bus im Schnitt nur halb so schnell wie seine Höchstgeschwindigkeit, deshalb zählen diese Phasen nur halb. Unfallgutachter rekonstruieren aus solchen Aufzeichnungen, wo ein Fahrzeug wann war.", "Area under the speed curve equals distance: that's already the basic idea of integration. While accelerating and braking the bus travels on average at only half its top speed, which is why those phases count only half. Accident investigators use such recordings to reconstruct where a vehicle was and when."),
            )
        },
        // ------------------------------------------------ Kräfte
        mc("phy.tischdecke", Topic.Forces, E,
            t("Beim berühmten Trick zieht jemand mit einem Ruck die Tischdecke weg, und Teller und Gläser bleiben fast an Ort und Stelle stehen. Warum klappt das nur, wenn man sehr schnell zieht?", "In the famous trick someone whips the tablecloth away with a jerk, and the plates and glasses stay almost where they were. Why does it only work if you pull very fast?"),
            t("Grund", "Reason"),
            t("Die Reibungskraft wirkt nur ganz kurz, und in so kurzer Zeit bringt sie das schwere Geschirr kaum in Bewegung.", "The friction force only acts very briefly, and in such a short time it barely gets the heavy crockery moving."),
            listOf(t("Beim schnellen Ziehen gibt es gar keine Reibung.", "When you pull fast there's no friction at all."), t("Die Luft drückt das Geschirr fest auf den Tisch.", "The air presses the crockery firmly onto the table."), t("Schnelle Bewegung macht das Geschirr schwerer.", "Fast movement makes the crockery heavier.")),
            t("Kernidee: Wie stark sich etwas in Bewegung setzt, hängt von Kraft mal Zeit ab, nicht nur von der Kraft.", "Key idea: how much something gets moving depends on force times time, not just on the force."),
            t("Gleitreibung ist ungefähr unabhängig vom Tempo. Was ändert sich also beim schnellen Ziehen?", "Sliding friction is roughly independent of speed. So what changes when you pull fast?"),
            t("Die Reibung ist beim schnellen und beim langsamen Ziehen etwa gleich groß, aber beim Ruck wirkt sie nur Sekundenbruchteile. Der Kraftstoß ist winzig, das Geschirr bekommt kaum Geschwindigkeit und bleibt durch seine Trägheit fast stehen.", "Friction is about the same whether you pull fast or slowly, but with a jerk it only acts for a fraction of a second. The impulse is tiny, the crockery gains hardly any speed, and its inertia keeps it almost in place."),
            t("Das ist Newtons erstes Gesetz in Aktion: Ein Körper bleibt in Ruhe, solange keine Kraft lange genug auf ihn wirkt. Schweres Geschirr hilft, weil es mehr Trägheit hat, eine glatte Decke ohne Saum ebenfalls. Derselbe Gedanke steckt im Kraftstoß F · Δt, mit dem man Airbags, Knautschzonen und Fallschirmlandungen versteht.", "This is Newton's first law in action: a body stays at rest as long as no force acts on it for long enough. Heavy crockery helps because it has more inertia, as does a smooth cloth without a hem. The same idea is behind the impulse F · Δt, which explains airbags, crumple zones and parachute landings."),
        ),
        // ------------------------------------------------ Energie
        lab("phy.bremsscheiben", Topic.Energy, M, 0.55f) {
            val kmh = pick(100.0, 130.0, 80.0); val v = kmh / 3.6; val mCar = 1500.0
            val ek = 0.5 * mCar * v * v; val dT = ek / (4 * 8.0 * 460)
            task(
                question = l("Ein Auto (1500 kg) bremst aus ${n(kmh, 0)} km/h bis zum Stillstand. Angenommen, die ganze Bewegungsenergie landet als Wärme in den vier Bremsscheiben aus Stahl, je 8 kg schwer (c = 460 J/(kg·K)). Um wie viel werden sie wärmer?", "A car (1500 kg) brakes from ${n(kmh, 0)} km/h to a stop. Suppose all the kinetic energy ends up as heat in the four steel brake discs, each weighing 8 kg (c = 460 J/(kg·K)). By how much do they warm up?"),
                steps = listOf(num(l("Temperaturanstieg in K", "Temperature rise in K"), dT, "K", rel = 0.02, done = """§\Delta T \approx ${m(dT, 0)}\ \text{K}§""",
                    hints = listOf(l("Kernidee: Erst die Bewegungsenergie berechnen, dann mit Q = m · c · ΔT auf alle 32 kg Stahl verteilen.", "Key idea: first work out the kinetic energy, then spread it over all 32 kg of steel using Q = m · c · ΔT."), """§\tfrac{1}{2} m v^2 = 32\ \text{kg} \cdot 460\ \tfrac{\text{J}}{\text{kg K}} \cdot \Delta T§"""))),
                solution = listOf("""§E = \tfrac{1}{2} \cdot 1500 \cdot ${m(v, 1)}^2 \approx ${m(ek / 1000, 0)}\ \text{kJ},\quad \Delta T = \dfrac{${m(ek, 0)}}{14\,720} \approx ${m(dT, 0)}\ \text{K}§"""),
                background = l("Bremsen ist Energieumwandlung: Bewegung wird zu Wärme. Weil die Bewegungsenergie mit dem Quadrat der Geschwindigkeit wächst, heizt eine Bremsung aus 130 km/h die Scheiben fast dreimal so stark auf wie eine aus 80 km/h. Bei langen Passabfahrten können Bremsen so heiß werden, dass sie nachlassen, deshalb bremst man dort mit dem Motor. Elektroautos gewinnen einen Teil dieser Energie als Strom zurück.", "Braking is energy conversion: motion becomes heat. Because kinetic energy grows with the square of the speed, braking from 130 km/h heats the discs almost three times as much as braking from 80 km/h. On long mountain descents brakes can get so hot that they fade, which is why you use engine braking there. Electric cars recover part of this energy as electricity."),
            )
        },
        // ------------------------------------------------ Impuls / Schwerpunkt
        mc("phy.fosbury", Topic.Momentum, M,
            t("Kann ein Hochspringer eine Latte überqueren, während sein Körperschwerpunkt die ganze Zeit unter der Latte bleibt?", "Can a high jumper clear a bar while their centre of mass stays below the bar the whole time?"),
            t("Antwort", "Answer"),
            t("Ja: Biegt er den Körper rücklings über die Latte, kann der Schwerpunkt außerhalb des Körpers unter ihr hindurchlaufen.", "Yes: by arching their body backwards over the bar, the centre of mass can lie outside the body and pass beneath it."),
            listOf(t("Nein, der Schwerpunkt muss immer über der Latte sein.", "No, the centre of mass always has to be above the bar."), t("Nur wenn er mehr Anlauf nimmt.", "Only if they take a longer run-up."), t("Nur auf dem Mond.", "Only on the Moon.")),
            t("Kernidee: Der Schwerpunkt muss nicht im Körper liegen. Wo liegt der Schwerpunkt eines Hufeisens?", "Key idea: the centre of mass doesn't have to lie inside the body. Where is the centre of mass of a horseshoe?"),
            t("Beim Sprung im Bogen hängen Kopf und Beine unter der Latte, nur die Mitte ist oben.", "In an arched jump the head and legs hang below the bar; only the middle is above it."),
            t("Beim Fosbury-Flop liegt der Körper als Bogen über der Latte. Der Schwerpunkt liegt dann wie beim Hufeisen außerhalb des Körpers und kann einige Zentimeter unter der Latte bleiben, während Rücken, Hüfte und Beine nacheinander darüber gleiten.", "In the Fosbury flop the body forms an arch over the bar. Like with a horseshoe, the centre of mass then lies outside the body and can stay a few centimetres below the bar while the back, hips and legs slide over it one after another."),
            t("Die Höhe, die der Schwerpunkt erreicht, legt der Absprung fest, wie bei einem geworfenen Stein. Dick Fosbury gewann 1968 mit seiner neuen Technik Olympiagold, und seitdem springt fast jeder so. Der Trick ist, die Latte zu überqueren, ohne den Schwerpunkt höher als nötig heben zu müssen.", "The height the centre of mass reaches is set by the take-off, as with a thrown stone. Dick Fosbury won Olympic gold with his new technique in 1968, and since then almost everyone jumps this way. The trick is to get over the bar without having to lift the centre of mass any higher than necessary."),
        ),
        // ------------------------------------------------ Drehung
        lab("phy.korallentag", Topic.Rotation, H, 0.6f) {
            val (rings, age) = pick(400 to 400, 395 to 350, 410 to 450)
            val hours = 365.25 * 24 / rings
            task(
                question = l("Korallen legen jeden Tag eine feine Wachstumsschicht an und dazu jedes Jahr ein dickeres Band. Fossile Korallen von vor etwa ${age} Millionen Jahren zeigen rund ${rings} Tagesschichten pro Jahr. Die Länge des Jahres war damals praktisch dieselbe wie heute. Wie viele Stunden hatte ein Tag?", "Corals lay down a thin growth layer every day and a thicker band each year. Fossil corals from about ${age} million years ago show around ${rings} daily layers per year. The length of the year was practically the same then as now. How many hours did a day have?"),
                steps = listOf(num(l("Tageslänge in Stunden", "Day length in hours"), hours, "h", rel = 0.01, done = """§\approx ${m(hours, 1)}\ \text{h}§""",
                    hints = listOf(l("Kernidee: Das Jahr hat damals wie heute gut 8766 Stunden. Sie verteilen sich auf mehr Tage.", "Key idea: then as now, the year had just over 8766 hours. They were shared among more days."), """§\dfrac{365{,}25 \cdot 24\ \text{h}}{${rings}}§"""))),
                solution = listOf("""§\dfrac{8766\ \text{h}}{${rings}} \approx ${m(hours, 1)}\ \text{h}§"""),
                background = l("Die Erde dreht sich immer langsamer. Der Mond zieht über die Gezeiten an den Ozeanen, und die Reibung bremst die Erdrotation. Der Drehimpuls geht dabei nicht verloren, er wandert zum Mond, der sich deshalb jedes Jahr um 3,8 cm von uns entfernt. Das misst man heute mit Laserpulsen, die an Reflektoren auf dem Mond zurückgeworfen werden. Ein Tag wird so etwa 2 Millisekunden pro Jahrhundert länger.", "The Earth is spinning ever more slowly. Through the tides, the Moon pulls on the oceans, and the friction brakes the Earth's rotation. The angular momentum isn't lost; it moves to the Moon, which therefore recedes from us by 3.8 cm every year. Today this is measured with laser pulses bounced off reflectors on the Moon. A day thus gets about 2 milliseconds longer per century."),
            )
        },
        // ------------------------------------------------ Gravitation
        lab("phy.mondapfel", Topic.Gravity, M, 0.55f) {
            val r = 3.844e8; val tt = 27.32 * 86400; val a = 4 * PI * PI * r / (tt * tt)
            task(
                question = l("Newtons berühmter Test: Fällt der Mond wie ein Apfel? Der Mond kreist in 384.400 km Abstand in 27,32 Tagen um die Erde. Wie groß ist seine Zentripetalbeschleunigung, in Millimetern pro Sekunde zum Quadrat?", "Newton's famous test: does the Moon fall like an apple? The Moon orbits the Earth at a distance of 384,400 km in 27.32 days. How large is its centripetal acceleration, in millimetres per second squared?"),
                steps = listOf(num(l("Beschleunigung in mm/s²", "Acceleration in mm/s²"), a * 1000, "mm/s²", rel = 0.02, done = """§a \approx ${m(a * 1000, 2)}\ \text{mm/s}^2§""",
                    hints = listOf(l("Kernidee: Für eine Kreisbahn gilt a = ω² · r, mit ω = 2π/T. Rechne die Tage in Sekunden um.", "Key idea: for a circular orbit a = ω² · r, with ω = 2π/T. Convert the days into seconds."), """§a = \dfrac{4\pi^2 r}{T^2}§"""))),
                solution = listOf("""§a = \dfrac{4\pi^2 \cdot 3{,}844 \cdot 10^8\ \text{m}}{(2{,}36 \cdot 10^6\ \text{s})^2} \approx ${m(a * 1000, 2)}\ \text{mm/s}^2§""", l("""Vergleich: §g / 60^2 = 9{,}81 / 3600 \approx 2{,}72\ \text{mm/s}^2§""", """Comparison: §g / 60^2 = 9{,}81 / 3600 \approx 2{,}72\ \text{mm/s}^2§""")),
                background = l("Der Mond ist etwa 60 Erdradien entfernt. Wenn die Schwerkraft mit dem Quadrat des Abstands abnimmt, sollte sie dort 60² = 3600-mal schwächer sein als am Boden, also 2,72 mm/s². Genau so stark muss der Mond zur Erde hin beschleunigt werden, um auf seiner Bahn zu bleiben. Newton erkannte so, dass dieselbe Kraft den Apfel fallen lässt und den Mond hält: Der Mond fällt ständig, verfehlt die Erde aber.", "The Moon is about 60 Earth radii away. If gravity falls off with the square of the distance, it should be 60² = 3600 times weaker there than at the ground, i.e. 2.72 mm/s². That's exactly how strongly the Moon must be accelerated towards the Earth to stay in its orbit. That's how Newton realised that the same force makes the apple fall and holds the Moon: the Moon is falling all the time, but it keeps missing the Earth."),
            )
        },
        // ------------------------------------------------ Schwingungen
        mc("phy.pendelmasse", Topic.Oscillations, E,
            t("Zwei Pendel sind gleich lang. An einem hängt eine Bleikugel, am anderen eine viermal leichtere Holzkugel. Welches schwingt schneller hin und her? (Luftwiderstand vernachlässigt)", "Two pendulums are the same length. One has a lead ball, the other a wooden ball four times lighter. Which one swings back and forth faster? (Ignore air resistance.)"),
            t("Antwort", "Answer"),
            t("Beide gleich schnell", "Both equally fast"),
            listOf(t("Das mit der Bleikugel", "The one with the lead ball"), t("Das mit der Holzkugel", "The one with the wooden ball"), t("Das mit der Holzkugel, und zwar doppelt so schnell", "The one with the wooden ball, twice as fast")),
            t("Kernidee: Eine schwerere Kugel wird stärker nach unten gezogen, ist aber auch genau so viel träger.", "Key idea: a heavier ball is pulled down more strongly, but it's also exactly that much more sluggish."),
            t("In der Pendelformel kommen nur die Länge und g vor.", "Only the length and g appear in the pendulum formula."),
            t("""Die Schwingungsdauer §T = 2\pi \sqrt{L/g}§ hängt nur von der Länge ab. Mehr Masse bedeutet mehr Gewichtskraft, aber auch mehr Trägheit, beides hebt sich genau auf.""", """The period §T = 2\pi \sqrt{L/g}§ depends only on the length. More mass means more weight, but also more inertia, and the two cancel exactly."""),
            t("Galileo soll das als junger Mann an einem schwingenden Kronleuchter im Dom von Pisa bemerkt haben, den Puls als Uhr. Dass schwere und leichte Körper gleich schnell fallen und gleich schnell schwingen, ist dieselbe Tatsache: Schwere und träge Masse sind gleich. Einstein machte genau daraus den Ausgangspunkt der Allgemeinen Relativitätstheorie.", "Galileo is said to have noticed this as a young man watching a swinging chandelier in Pisa cathedral, using his pulse as a clock. That heavy and light bodies fall equally fast and swing equally fast is the same fact: gravitational and inertial mass are equal. Einstein made exactly this the starting point of general relativity."),
        ),
        // ------------------------------------------------ Materie
        mc("phy.nadelschwimmt", Topic.Matter, E,
            t("Legt man eine Büroklammer aus Stahl vorsichtig flach auf Wasser, bleibt sie oben liegen, obwohl Stahl achtmal so dicht ist wie Wasser. Gibt man einen Tropfen Spülmittel dazu, geht sie sofort unter. Was trägt sie?", "If you carefully lay a steel paper clip flat on water, it stays on top, even though steel is eight times as dense as water. Add a drop of washing-up liquid and it sinks at once. What holds it up?"),
            t("Grund", "Reason"),
            t("Die Oberflächenspannung: Die Wasserteilchen an der Oberfläche halten wie eine gespannte Haut zusammen.", "Surface tension: the water particles at the surface hold together like a stretched skin."),
            listOf(t("Der Auftrieb, wie bei einem Schiff", "Buoyancy, as with a ship"), t("Luftbläschen, die an der Klammer kleben", "Air bubbles stuck to the clip"), t("Magnetische Kräfte im Wasser", "Magnetic forces in the water")),
            t("Kernidee: Schau genau hin: Die Wasseroberfläche wird unter der Klammer leicht eingedellt, wie ein Trampolin.", "Key idea: look closely: the water surface is slightly dented under the clip, like a trampoline."),
            t("Spülmittel schwächt die Anziehung zwischen den Wasserteilchen an der Oberfläche.", "Washing-up liquid weakens the attraction between the water particles at the surface."),
            t("Wasserteilchen ziehen sich gegenseitig an. An der Oberfläche fehlen Nachbarn nach oben, deshalb verhält sie sich wie eine elastische Haut. Die eingedellte Haut drückt die Klammer nach oben. Spülmittel senkt die Oberflächenspannung, und die Haut reißt.", "Water particles attract each other. At the surface there are no neighbours above, so it behaves like an elastic skin. The dented skin pushes the clip upwards. Washing-up liquid lowers the surface tension, and the skin breaks."),
            t("Wasserläufer laufen genau so über Teiche, ihre Beine sind zusätzlich wasserabweisend. Die Oberflächenspannung macht Tropfen rund und lässt Wasser in dünnen Röhrchen aufsteigen. Wasser hat sie besonders stark, wegen der Wasserstoffbrücken zwischen seinen Molekülen.", "Pond skaters walk across ponds in exactly this way, and their legs are also water-repellent. Surface tension makes drops round and lets water rise in thin tubes. Water has an especially strong one, because of the hydrogen bonds between its molecules."),
        ),
        lab("phy.kapillare", Topic.Matter, H, 0.6f) {
            val rUm = pick(20.0, 10.0, 50.0); val r = rUm * 1e-6
            val h = 2 * 0.072 / (1000 * 9.81 * r)
            task(
                question = l("In den Leitungsbahnen einer Pflanze steigt Wasser durch Kapillarkräfte auf. Wie hoch kommt es in einem Röhrchen mit ${n(rUm, 0)} µm Radius? Oberflächenspannung von Wasser: 0,072 N/m, die Wand wird vollständig benetzt.", "In a plant's vessels water rises by capillary action. How high does it get in a tube of ${n(rUm, 0)} µm radius? Surface tension of water: 0.072 N/m, and the wall is completely wetted."),
                steps = listOf(num(l("Steighöhe in m", "Height in m"), h, "m", rel = 0.02, done = """§h \approx ${m(h, 2)}\ \text{m}§""",
                    hints = listOf(l("Kernidee: Die Oberflächenspannung zieht am ganzen Rand des Röhrchens nach oben (Kraft 2πr · σ). Sie hält eine Wassersäule mit dem Gewicht ρ · πr²h · g.", "Key idea: surface tension pulls upwards along the whole rim of the tube (force 2πr · σ). It holds up a column of water with weight ρ · πr²h · g."), """§h = \dfrac{2\sigma}{\rho g r}§"""))),
                solution = listOf("""§h = \dfrac{2 \cdot 0{,}072}{1000 \cdot 9{,}81 \cdot ${sci(r)}}\ \text{m} \approx ${m(h, 2)}\ \text{m}§"""),
                background = l("Je dünner das Röhrchen, desto höher steigt das Wasser, weil der Rand im Verhältnis zur Fläche wächst. So saugen Küchenpapier und Schwämme Wasser auf. Für einen 100 m hohen Mammutbaum reicht das aber bei Weitem nicht. Dort zieht die Verdunstung an den Blättern das Wasser hoch: Die Wassersäule hängt durch den Zusammenhalt der Moleküle wie ein Seil von oben herab.", "The thinner the tube, the higher the water rises, because the rim grows relative to the area. That's how kitchen paper and sponges soak up water. For a 100 m tall redwood, though, it's nowhere near enough. There, evaporation at the leaves pulls the water up: the column of water hangs down from the top like a rope, held together by the cohesion of the molecules."),
            )
        },
        // ------------------------------------------------ Wärme
        mc("phy.fliesen", Topic.Heat, E,
            t("Im Bad liegen Fliesen, im Flur ein Teppich. Beide haben seit Stunden genau Zimmertemperatur, 20 °C. Barfuß fühlen sich die Fliesen trotzdem viel kälter an. Warum?", "The bathroom has tiles, the hallway a carpet. Both have been at exactly room temperature, 20 °C, for hours. Barefoot, the tiles still feel much colder. Why?"),
            t("Grund", "Reason"),
            t("Fliesen leiten die Wärme viel schneller aus der Haut ab, und die Haut spürt den Wärmeverlust, nicht die Temperatur.", "Tiles conduct heat out of the skin much faster, and the skin senses the loss of heat, not the temperature."),
            listOf(t("Fliesen sind in Wirklichkeit kälter als der Teppich.", "Tiles are actually colder than the carpet."), t("Fliesen strahlen Kälte ab.", "Tiles radiate cold."), t("Teppich erzeugt durch Reibung Wärme.", "Carpet produces heat through friction.")),
            t("Kernidee: Ein Thermometer würde auf beiden 20 °C zeigen. Was misst also deine Haut?", "Key idea: a thermometer would show 20 °C on both. So what does your skin measure?"),
            t("Im Teppich steckt viel Luft, und Luft leitet Wärme sehr schlecht.", "The carpet is full of air, and air conducts heat very poorly."),
            t("Die Haut misst, wie schnell sie Wärme verliert. Keramik leitet Wärme etwa zwanzigmal besser als ein Teppich voller Luft, deshalb fließt die Wärme deines Fußes viel schneller ab, und es fühlt sich kalt an.", "The skin measures how fast it loses heat. Ceramic conducts heat about twenty times better than a carpet full of air, so the heat from your foot flows away much faster, and it feels cold."),
            t("Deshalb fühlt sich Metall bei Frost so eisig an und ein Holzgeländer daneben nicht. Bei heißen Gegenständen ist es umgekehrt: In einer 90 °C heißen Sauna kann man auf Holz sitzen, ein Metallnagel darin verbrennt die Haut. Unser Temperatursinn ist eigentlich ein Wärmestromsinn.", "That's why metal feels so icy in frost and a wooden railing next to it doesn't. With hot objects it's the other way round: in a sauna at 90 °C you can sit on wood, but a metal nail in it burns the skin. Our sense of temperature is really a sense of heat flow."),
        ),
        mc("phy.seegefriert", Topic.Heat, M,
            t("Im Winter friert ein See von oben her zu, und am Grund bleibt das Wasser bei etwa 4 °C flüssig, sodass die Fische überleben. Warum friert er nicht von unten nach oben?", "In winter a lake freezes from the top down, and at the bottom the water stays liquid at about 4 °C, so the fish survive. Why doesn't it freeze from the bottom up?"),
            t("Grund", "Reason"),
            t("Wasser ist bei 4 °C am dichtesten. Kälteres Wasser und Eis sind leichter und bleiben oben.", "Water is densest at 4 °C. Colder water and ice are lighter and stay on top."),
            listOf(t("Der Seegrund heizt das Wasser stark auf.", "The lake bed heats the water strongly."), t("Kaltes Wasser ist immer schwerer, deshalb sinkt es und erwärmt sich unten.", "Cold water is always heavier, so it sinks and warms up at the bottom."), t("Die Fische erzeugen genug Wärme.", "The fish produce enough heat.")),
            t("Kernidee: Bei fast allen Stoffen sinkt das Kalte nach unten. Wasser macht unterhalb von 4 °C eine Ausnahme.", "Key idea: in almost all substances the cold part sinks. Below 4 °C water is an exception."),
            t("Eis schwimmt. Was sagt das über seine Dichte?", "Ice floats. What does that say about its density?"),
            t("Bis 4 °C sinkt abgekühltes Wasser nach unten. Darunter dehnt es sich wieder aus, bleibt an der Oberfläche und gefriert dort. Die Eisschicht isoliert dann das Wasser darunter.", "Down to 4 °C, cooled water sinks to the bottom. Below that it expands again, stays at the surface and freezes there. The layer of ice then insulates the water beneath."),
            t("Diese Dichteanomalie liegt an den Wasserstoffbrücken: Je kälter, desto mehr ordnen sich die Moleküle zu einem lockeren Gitter mit viel Platz. Ohne sie würden Seen von unten durchfrieren und im Sommer kaum auftauen. Gefrierendes Wasser dehnt sich um etwa 9 % aus, das sprengt Felsen und lässt Wasserrohre platzen.", "This density anomaly is due to hydrogen bonds: the colder it gets, the more the molecules arrange themselves into a loose lattice with lots of space. Without it, lakes would freeze solid from the bottom up and barely thaw in summer. Freezing water expands by about 9%, which splits rocks and bursts water pipes."),
        ),
        // ------------------------------------------------ Wellen
        mc("phy.strandwellen", Topic.Waves, M,
            t("Egal aus welcher Richtung der Wind draußen auf dem Meer weht: Am Strand laufen die Wellen fast immer beinahe parallel zum Ufer ein. Warum?", "Whatever direction the wind blows from out at sea, at the beach the waves almost always arrive nearly parallel to the shore. Why?"),
            t("Grund", "Reason"),
            t("Im flachen Wasser werden Wellen langsamer, und der Teil, der zuerst flaches Wasser erreicht, bremst ab. Die Welle dreht sich zum Ufer hin.", "Waves slow down in shallow water, and the part that reaches shallow water first slows down. The wave swings round towards the shore."),
            listOf(t("Am Strand weht der Wind immer zum Land hin.", "At the beach the wind always blows towards the land."), t("Die Wellen werden vom Strand zurückgeworfen.", "The waves are reflected by the beach."), t("Das Wasser fließt insgesamt zum Ufer.", "The water as a whole flows towards the shore.")),
            t("Kernidee: Licht ändert die Richtung, wenn es in ein Medium läuft, in dem es langsamer ist. Für Wasserwellen ist flaches Wasser so ein Medium.", "Key idea: light changes direction when it enters a medium in which it travels more slowly. For water waves, shallow water is such a medium."),
            t("Stell dir eine schräg einlaufende Welle vor: Ein Ende ist schon im Flachen, das andere noch im Tiefen.", "Imagine a wave coming in at an angle: one end is already in the shallows, the other still in deep water."),
            t("Lange Wellen sind im flachen Wasser umso langsamer, je flacher es ist. Läuft eine Welle schräg ein, bremst die ufernahe Seite zuerst, und die Wellenfront schwenkt herum, bis sie fast parallel zum Ufer liegt. Das ist Brechung, wie bei Licht im Glas.", "Long waves in shallow water are slower the shallower it is. If a wave arrives at an angle, the side nearer the shore slows first and the wavefront swings round until it's almost parallel to the shore. This is refraction, like light in glass."),
            t("Aus demselben Grund brechen Wellen an Landzungen besonders heftig und laufen in Buchten ruhig aus: Die Wellenenergie wird auf Vorsprünge gelenkt. Surfer suchen Orte, an denen der Meeresboden die Wellen so formt, dass sie gleichmäßig brechen. Tsunamis werden auf demselben Weg beim Auflaufen höher.", "For the same reason waves break especially fiercely on headlands and run out calmly in bays: the wave energy is steered onto the points. Surfers look for places where the seabed shapes the waves so that they break evenly. Tsunamis grow taller in the same way as they run up onto the coast."),
        ),
        // ------------------------------------------------ Optik
        mc("phy.spiegelvertauscht", Topic.Optics, E,
            t("Hebst du vor dem Spiegel die rechte Hand, hebt dein Spiegelbild scheinbar die linke. Oben und unten vertauscht der Spiegel aber nicht. Was vertauscht er wirklich?", "If you raise your right hand in front of a mirror, your reflection seems to raise its left. But the mirror doesn't swap top and bottom. What does it really swap?"),
            t("Antwort", "Answer"),
            t("Vorne und hinten, also die Richtung zum Spiegel hin", "Front and back, i.e. the direction towards the mirror"),
            listOf(t("Links und rechts, weil unsere Augen nebeneinander liegen", "Left and right, because our eyes are side by side"), t("Links und rechts, weil der Spiegel senkrecht hängt", "Left and right, because the mirror hangs vertically"), t("Gar nichts, das ist eine Täuschung des Gehirns", "Nothing at all; it's an illusion of the brain")),
            t("Kernidee: Zeigt deine rechte Hand nach Osten, zeigt die Hand im Spiegel auch nach Osten. Und dein Kopf ist im Spiegel auch oben.", "Key idea: if your right hand points east, the hand in the mirror also points east. And your head is at the top in the mirror too."),
            t("Was passiert mit deiner Nase, die auf den Spiegel zeigt?", "What happens to your nose, which points at the mirror?"),
            t("Der Spiegel lässt links, rechts, oben und unten an ihrem Platz und kehrt nur die Richtung senkrecht zu seiner Fläche um. Deine Nase zeigt nach vorn, die im Spiegel nach hinten. Weil wir uns vorstellen, uns umzudrehen, um an der Stelle des Spiegelbilds zu stehen, deuten wir das als Links-rechts-Tausch.", "The mirror leaves left, right, up and down in place and only reverses the direction perpendicular to its surface. Your nose points forward, the one in the mirror backwards. Because we imagine turning round to stand where the reflection is, we interpret that as a left–right swap."),
            t("Deshalb steht auf Krankenwagen „Notarzt“ in Spiegelschrift: Im Rückspiegel des Autos davor liest man es richtig. Ein Spiegelbild ist kein gedrehtes, sondern ein gespiegeltes Objekt: Eine rechte Hand wird zu einer linken, und kein Drehen im Raum kann das rückgängig machen. Chemiker kennen das bei Molekülen, deren Spiegelbilder anders wirken.", "That's why emergency vehicles have their name in mirror writing: in the rear-view mirror of the car ahead it reads correctly. A mirror image isn't a rotated object but a reflected one: a right hand becomes a left hand, and no rotation in space can undo that. Chemists know this from molecules whose mirror images act differently."),
        ),
        mc("phy.prisma", Topic.Optics, E,
            t("Weißes Licht fällt durch ein Glasprisma und wird zu einem Regenbogenband aufgefächert. Welche Farbe wird am stärksten abgelenkt?", "White light passes through a glass prism and is fanned out into a band of rainbow colours. Which colour is bent the most?"),
            t("Farbe", "Colour"),
            t("Violett", "Violet"),
            listOf(t("Rot", "Red"), t("Grün", "Green"), t("Alle gleich stark, die Farben entstehen erst im Auge", "All equally; the colours only arise in the eye")),
            t("Kernidee: Die Brechzahl von Glas ist für verschiedene Wellenlängen ein wenig verschieden. Kurzwelliges Licht ist im Glas etwas langsamer.", "Key idea: the refractive index of glass is slightly different for different wavelengths. Short-wavelength light is a little slower in glass."),
            t("Violett hat die kürzeste Wellenlänge im sichtbaren Licht.", "Violet has the shortest wavelength of visible light."),
            t("Kurzwelliges Licht wird im Glas stärker gebremst und deshalb stärker gebrochen. Violett liegt am weitesten vom ursprünglichen Strahl entfernt, Rot am nächsten.", "Short-wavelength light is slowed more in glass and therefore bent more. Violet ends up furthest from the original beam, red closest."),
            t("Isaac Newton zeigte 1666, dass die Farben im weißen Licht schon stecken: Mit einem zweiten, umgedrehten Prisma setzte er sie wieder zu Weiß zusammen. Diese Dispersion erzeugt auch Regenbögen und das Funkeln geschliffener Diamanten. Bei Kameraobjektiven ist sie dagegen lästig, farbige Säume an Kanten heißen dort chromatische Aberration.", "In 1666 Isaac Newton showed that the colours are already contained in white light: with a second, inverted prism he combined them back into white. This dispersion also creates rainbows and the sparkle of cut diamonds. In camera lenses, by contrast, it's a nuisance: coloured fringes at edges are called chromatic aberration."),
        ),
        // ------------------------------------------------ Elektrizität
        mc("phy.hausparallel", Topic.Electricity, E,
            t("In einer Wohnung hängen Lampen, Kühlschrank und Fernseher an denselben Leitungen. Warum sind sie parallel geschaltet und nicht hintereinander in Reihe?", "In a flat, the lamps, fridge and TV are on the same wiring. Why are they connected in parallel and not one after another in series?"),
            t("Grund", "Reason"),
            t("So bekommt jedes Gerät die vollen 230 V und funktioniert unabhängig davon, ob die anderen an oder aus sind.", "That way every device gets the full 230 V and works regardless of whether the others are on or off."),
            listOf(t("Parallel verbraucht insgesamt weniger Strom.", "Parallel uses less electricity overall."), t("In Reihe würden die Kabel zu heiß.", "In series the cables would get too hot."), t("Das ist nur aus Gewohnheit so, Reihe ginge genauso gut.", "It's only habit; series would work just as well.")),
            t("Kernidee: Was passiert in einer Reihenschaltung, wenn ein Gerät ausgeschaltet wird oder kaputtgeht?", "Key idea: what happens in a series circuit if one device is switched off or breaks?"),
            t("In Reihe teilen sich die Geräte außerdem die Spannung.", "In series, the devices also share the voltage."),
            t("In Reihe würde jedes Ausschalten den ganzen Kreis unterbrechen, und die Geräte müssten sich die Spannung teilen. Parallel liegt jedes Gerät direkt an der vollen Netzspannung und hat seinen eigenen Stromweg.", "In series, switching anything off would break the whole circuit, and the devices would have to share the voltage. In parallel each device sits directly across the full mains voltage and has its own path for current."),
            t("Der Preis dafür: Die Ströme aller eingeschalteten Geräte addieren sich in der Zuleitung. Deshalb schützt jede Leitung eine Sicherung, meist für 16 A, also gut 3600 W. Alte Lichterketten waren dagegen in Reihe geschaltet, und eine einzige kaputte Birne ließ die ganze Kette dunkel werden.", "The price for this: the currents of all the devices that are switched on add up in the supply cable. That's why each circuit is protected by a fuse, usually 16 A, i.e. a good 3600 W. Old fairy lights, by contrast, were wired in series, and a single broken bulb made the whole string go dark."),
        ),
        // ------------------------------------------------ Felder
        mc("phy.feldlinien", Topic.Fields, E,
            t("Elektrische Feldlinien zeigen, in welche Richtung eine positive Probeladung gezogen würde. Können sich zwei Feldlinien kreuzen?", "Electric field lines show the direction in which a positive test charge would be pulled. Can two field lines cross?"),
            t("Antwort", "Answer"),
            t("Nein, sonst hätte das Feld an der Kreuzung zwei verschiedene Richtungen.", "No, otherwise the field would have two different directions at the crossing point."),
            listOf(t("Ja, wenn zwei Ladungen nah beieinander sind.", "Yes, if two charges are close together."), t("Ja, aber nur in Leitern.", "Yes, but only in conductors."), t("Ja, dort ist das Feld besonders stark.", "Yes, the field is especially strong there.")),
            t("Kernidee: An jedem Punkt hat das Feld genau eine Richtung, die Richtung der Gesamtkraft.", "Key idea: at every point the field has exactly one direction, the direction of the total force."),
            t("Was müsste eine Probeladung genau am Kreuzungspunkt tun?", "What would a test charge have to do exactly at the crossing point?"),
            t("Feldlinien folgen an jedem Punkt der Richtung der Kraft. Eine Ladung kann nicht gleichzeitig in zwei Richtungen gezogen werden, die Kräfte mehrerer Ladungen addieren sich zu einer einzigen. Deshalb kreuzen sich Feldlinien nie, sie können nur an Ladungen beginnen oder enden.", "Field lines follow the direction of the force at every point. A charge can't be pulled in two directions at once; the forces from several charges add up to a single one. That's why field lines never cross; they can only start or end at charges."),
            t("Feldlinien erfand Michael Faraday, der kaum Mathematik konnte, aber ein großartiges räumliches Vorstellungsvermögen hatte. Wo sie dicht liegen, ist das Feld stark. James Clerk Maxwell übersetzte Faradays Bilder später in Gleichungen, aus denen die Existenz von Licht als elektromagnetischer Welle folgte.", "Field lines were invented by Michael Faraday, who knew hardly any mathematics but had a superb spatial imagination. Where they lie close together, the field is strong. James Clerk Maxwell later translated Faraday's pictures into equations, from which the existence of light as an electromagnetic wave followed."),
        ),
        // ------------------------------------------------ Magnetismus
        mc("phy.kompassnord", Topic.Magnetism, E,
            t("Der Nordpol einer Kompassnadel zeigt nach Norden. Ungleiche Pole ziehen sich an. Was für ein Magnetpol liegt dann in der Nähe des geografischen Nordpols?", "The north pole of a compass needle points north. Opposite poles attract. So what kind of magnetic pole lies near the geographic North Pole?"),
            t("Antwort", "Answer"),
            t("Ein magnetischer Südpol", "A magnetic south pole"),
            listOf(t("Ein magnetischer Nordpol", "A magnetic north pole"), t("Gar keiner, die Nadel folgt der Erddrehung", "None at all; the needle follows the Earth's rotation"), t("Abwechselnd Nord- und Südpol", "Alternately north and south pole")),
            t("Kernidee: Der Nordpol der Nadel wird angezogen. Welcher Pol zieht einen Nordpol an?", "Key idea: the needle's north pole is attracted. Which pole attracts a north pole?"),
            t("Die Bezeichnung „Nordpol“ der Nadel heißt nur: das Ende, das nach Norden zeigt.", "The name 'north pole' of the needle only means: the end that points north."),
            t("Weil sich ungleiche Pole anziehen, muss im Norden ein magnetischer Südpol liegen. Die Namen sind historisch: Man benannte die Enden der Nadel danach, wohin sie zeigen.", "Because opposite poles attract, there must be a magnetic south pole in the north. The names are historical: the ends of the needle were named after where they point."),
            t("Der magnetische Pol liegt zudem nicht genau am geografischen Nordpol, sondern wandert, derzeit um rund 50 km pro Jahr von Kanada Richtung Sibirien. Über Jahrhunderttausende kehrt sich das Erdmagnetfeld sogar ganz um, das letzte Mal vor etwa 780.000 Jahren. Erzeugt wird es durch strömendes flüssiges Eisen im äußeren Erdkern.", "The magnetic pole also isn't exactly at the geographic North Pole but wanders, currently by around 50 km a year from Canada towards Siberia. Over hundreds of thousands of years the Earth's magnetic field even flips completely, the last time about 780,000 years ago. It's generated by flowing liquid iron in the outer core."),
        ),
        // ------------------------------------------------ Relativität
        mc("phy.kausalitaet", Topic.Relativity, M,
            t("Ein Stern in 100 Lichtjahren Entfernung ist (in unserem Bezugssystem gerechnet) vor 60 Jahren explodiert. Kann diese Explosion heute schon irgendeine Wirkung auf der Erde haben?", "A star 100 light years away exploded 60 years ago (reckoned in our frame of reference). Can this explosion already have any effect on Earth today?"),
            t("Antwort", "Answer"),
            t("Nein, keine Wirkung kann schneller als das Licht sein. Wir erfahren erst in 40 Jahren davon.", "No, no effect can travel faster than light. We'll only find out about it in 40 years."),
            listOf(t("Ja, die Schwerkraft wirkt sofort über jede Entfernung.", "Yes, gravity acts instantly over any distance."), t("Ja, über Neutrinos, die schneller als Licht sind.", "Yes, via neutrinos, which are faster than light."), t("Ja, wenn wir mit einem sehr guten Teleskop hinschauen.", "Yes, if we look with a very good telescope.")),
            t("Kernidee: Alle Signale, auch Licht, Schwerkraftwellen und Teilchen, sind höchstens so schnell wie das Licht.", "Key idea: all signals, including light, gravitational waves and particles, are at most as fast as light."),
            t("Licht braucht für 100 Lichtjahre 100 Jahre. 60 Jahre sind vergangen.", "Light takes 100 years to cover 100 light years. 60 years have passed."),
            t("Das Ereignis liegt außerhalb unseres Lichtkegels: Kein Signal konnte uns bisher erreichen. Für uns hat die Explosion in gewissem Sinn noch gar nicht stattgefunden, weder sichtbar noch spürbar.", "The event lies outside our light cone: no signal could have reached us yet. For us, in a certain sense, the explosion hasn't happened yet, neither visibly nor in any other way."),
            t("Die Lichtgeschwindigkeit ist in der Relativitätstheorie die Höchstgeschwindigkeit für Ursache und Wirkung. Wäre etwas schneller, könnte es in manchen Bezugssystemen die Wirkung vor der Ursache geben. Auch Gravitationswellen laufen mit Lichtgeschwindigkeit: 2017 kamen die Wellen zweier verschmelzender Neutronensterne fast gleichzeitig mit ihrem Licht an, nach 130 Millionen Jahren Reise.", "In relativity, the speed of light is the speed limit for cause and effect. If anything were faster, in some frames of reference the effect could come before the cause. Gravitational waves also travel at the speed of light: in 2017 the waves from two merging neutron stars arrived almost at the same moment as their light, after a journey of 130 million years."),
        ),
        // ------------------------------------------------ Quanten
        lab("phy.sonnensegel", Topic.Quantum, H, 0.65f) {
            val area = pick(100.0, 196.0, 1000.0); val f = 2 * 1361 * area / 3e8
            task(
                question = l("Licht hat Impuls. Ein Sonnensegel mit ${n(area, 0)} m² steht senkrecht zur Sonne, in Erdentfernung (1361 W/m²), und spiegelt das Licht vollständig zurück. Mit welcher Kraft drückt das Licht auf das Segel, in Millinewton?", "Light carries momentum. A solar sail of ${n(area, 0)} m² faces the Sun at the Earth's distance (1361 W/m²) and reflects the light completely. With what force does the light push on the sail, in millinewtons?"),
                steps = listOf(num(l("Kraft in mN", "Force in mN"), f * 1000, "mN", rel = 0.02, done = """§F \approx ${m(f * 1000, 2)}\ \text{mN}§""",
                    hints = listOf(l("Kernidee: Licht mit der Leistung P trägt pro Sekunde den Impuls P/c. Beim Zurückspiegeln kehrt er sich um, die Änderung ist doppelt so groß.", "Key idea: light with power P carries momentum P/c per second. When reflected it reverses, so the change is twice as big."), """§F = \dfrac{2 I A}{c}§"""))),
                solution = listOf("""§F = \dfrac{2 \cdot 1361 \cdot ${m(area, 0)}}{3 \cdot 10^8}\ \text{N} \approx ${m(f * 1000, 2)}\ \text{mN}§"""),
                background = l("Das ist winzig, etwa das Gewicht eines Sandkorns pro Quadratmeter. Aber im Weltall gibt es keine Reibung, und die Kraft wirkt ununterbrochen, ohne dass Treibstoff verbraucht wird. 2010 entfaltete die japanische Sonde IKAROS als erste ein Sonnensegel von 14 × 14 m und wurde allein durch Licht beschleunigt. Dass Photonen Impuls haben, p = E/c, ist eine Folge der Relativitätstheorie und der Quantenphysik.", "That's tiny, about the weight of a grain of sand per square metre. But in space there's no friction, and the force acts continuously without using any fuel. In 2010 the Japanese probe IKAROS was the first to unfurl a solar sail, 14 × 14 m, and was accelerated by light alone. That photons carry momentum, p = E/c, follows from relativity and quantum physics."),
            )
        },
        // ------------------------------------------------ Kerne
        mc("phy.sonnentunnel", Topic.Nuclear, H,
            t("Damit zwei Protonen verschmelzen, müssten sie sich trotz elektrischer Abstoßung extrem nahe kommen. Rechnet man nach, reichen die 15 Millionen Grad im Sonnenkern dafür eigentlich nicht aus. Warum brennt die Sonne trotzdem?", "For two protons to fuse, they'd have to get extremely close despite their electric repulsion. If you do the calculation, the 15 million degrees in the Sun's core aren't actually enough for that. So why does the Sun burn anyway?"),
            t("Grund", "Reason"),
            t("Durch den Tunneleffekt: Protonen können die Abstoßungsbarriere mit kleiner Wahrscheinlichkeit durchdringen, ohne sie zu überwinden.", "Through quantum tunnelling: protons can pass through the repulsive barrier with a small probability, without getting over it."),
            listOf(t("Der Druck im Kern schaltet die elektrische Abstoßung ab.", "The pressure in the core switches off the electric repulsion."), t("Im Sonnenkern ist es in Wirklichkeit viel heißer.", "It's actually much hotter in the Sun's core."), t("Die Sonne verbrennt Wasserstoff chemisch mit Sauerstoff.", "The Sun burns hydrogen chemically with oxygen.")),
            t("Kernidee: In der Quantenphysik sind Teilchen auch Wellen, und eine Welle kann ein Stück weit in eine Barriere eindringen.", "Key idea: in quantum physics particles are also waves, and a wave can penetrate some way into a barrier."),
            t("Ein Rastertunnelmikroskop nutzt denselben Effekt für Elektronen.", "A scanning tunnelling microscope uses the same effect for electrons."),
            t("Klassisch hätte kaum ein Proton genug Energie. Quantenmechanisch gibt es eine winzige Wahrscheinlichkeit, durch die Barriere zu tunneln. Bei unvorstellbar vielen Zusammenstößen pro Sekunde passiert das oft genug.", "Classically hardly any proton would have enough energy. Quantum-mechanically there's a tiny probability of tunnelling through the barrier. With an unimaginable number of collisions per second, it happens often enough."),
            t("George Gamow erkannte 1928 den Tunneleffekt beim Alphazerfall, und kurz darauf wurde klar, dass er auch die Kernfusion in Sternen möglich macht. Weil das Tunneln so selten gelingt, brennt die Sonne langsam und gleichmäßig über Milliarden Jahre, statt auf einmal zu explodieren. Ohne Quantenmechanik gäbe es keine leuchtenden Sterne.", "In 1928 George Gamow recognised tunnelling in alpha decay, and soon afterwards it became clear that it also makes nuclear fusion in stars possible. Because tunnelling succeeds so rarely, the Sun burns slowly and steadily for billions of years instead of exploding all at once. Without quantum mechanics there would be no shining stars."),
        ),
        // ------------------------------------------------ Moderne Physik
        mc("phy.pet", Topic.Modern, M,
            t("Bei der Positronen-Emissions-Tomografie (PET) zerstrahlt ein Positron im Körper mit einem Elektron. Die Detektoren suchen nach zwei Gammaphotonen, die gleichzeitig in genau entgegengesetzte Richtungen fliegen. Warum fliegen sie immer entgegengesetzt?", "In positron emission tomography (PET) a positron annihilates with an electron in the body. The detectors look for two gamma photons that fly off at the same moment in exactly opposite directions. Why do they always fly in opposite directions?"),
            t("Grund", "Reason"),
            t("Wegen der Impulserhaltung: Elektron und Positron ruhen fast, also muss der Gesamtimpuls der Photonen null sein.", "Because of conservation of momentum: the electron and positron are almost at rest, so the photons' total momentum must be zero."),
            listOf(t("Weil sie sich elektrisch abstoßen", "Because they repel each other electrically"), t("Weil der Detektor sie so ausrichtet", "Because the detector lines them up that way"), t("Zufall, sie könnten auch in dieselbe Richtung fliegen", "Chance; they could also fly in the same direction")),
            t("Kernidee: Vorher ist der Gesamtimpuls fast null. Was muss danach gelten?", "Key idea: beforehand the total momentum is almost zero. What must hold afterwards?"),
            t("Photonen sind ungeladen, Abstoßung scheidet aus.", "Photons are uncharged, so repulsion is ruled out."),
            t("Der Impuls vorher ist null, also auch nachher. Zwei Photonen mit gleich großem Impuls heben sich nur auf, wenn sie entgegengesetzt fliegen. Aus der Energieerhaltung folgt, dass jedes 511 keV hat, die Ruheenergie eines Elektrons.", "The momentum before is zero, so it's zero afterwards too. Two photons with equal momentum only cancel if they fly in opposite directions. From energy conservation it follows that each has 511 keV, the rest energy of an electron."),
            t("Die Detektoren sitzen deshalb in einem Ring um den Patienten. Treffen zwei Photonen gleichzeitig gegenüberliegende Detektoren, lag der Zerfall irgendwo auf der Verbindungslinie, und aus Millionen solcher Linien rechnet der Computer ein 3D-Bild. Als Quelle dient meist radioaktiver Traubenzucker, der sich dort sammelt, wo besonders viel Energie verbraucht wird, etwa in Tumoren. Antimaterie ist hier Alltag in der Klinik.", "That's why the detectors sit in a ring around the patient. If two photons hit opposite detectors at the same moment, the decay happened somewhere on the line between them, and from millions of such lines a computer reconstructs a 3D image. The source is usually radioactive glucose, which collects where a lot of energy is being used, for instance in tumours. Antimatter is everyday clinical practice here."),
        ),
        // ------------------------------------------------ Astro
        mc("phy.mondphasen", Topic.Astro, E,
            t("Warum sieht der Mond im Lauf eines Monats mal rund, mal halb und mal wie eine schmale Sichel aus?", "Why does the Moon look round at some times of the month, half at others and like a thin crescent at others?"),
            t("Grund", "Reason"),
            t("Die Sonne beleuchtet immer eine Hälfte des Mondes. Je nach seiner Stellung sehen wir mehr oder weniger von dieser beleuchteten Hälfte.", "The Sun always lights up one half of the Moon. Depending on its position we see more or less of this lit half."),
            listOf(t("Der Schatten der Erde fällt auf den Mond.", "The Earth's shadow falls on the Moon."), t("Wolken verdecken Teile des Mondes.", "Clouds cover parts of the Moon."), t("Der Mond leuchtet selbst mal stärker und mal schwächer.", "The Moon itself glows sometimes more and sometimes less.")),
            t("Kernidee: Bei Halbmond steht der Mond am Himmel etwa 90° von der Sonne entfernt. Wo müsste die Erde dann stehen, damit ihr Schatten auf den Mond fällt?", "Key idea: at half moon the Moon is about 90° from the Sun in the sky. Where would the Earth have to be for its shadow to fall on the Moon?"),
            t("Beleuchte einen Ball mit einer Lampe und geh um ihn herum.", "Light a ball with a lamp and walk round it."),
            t("Bei Vollmond steht der Mond der Sonne gegenüber, und wir sehen die ganze beleuchtete Seite. Bei Neumond steht er zwischen uns und der Sonne, wir sehen nur seine dunkle Seite. Dazwischen sehen wir einen Teil der hellen Hälfte.", "At full moon the Moon is opposite the Sun, and we see the whole lit side. At new moon it's between us and the Sun, and we only see its dark side. In between we see part of the bright half."),
            t("Der Erdschatten trifft den Mond nur bei einer Mondfinsternis, und die gibt es nur bei Vollmond. Die Sichel einer Mondphase ist immer zur Sonne hin gewölbt, der Erdschatten dagegen ist ein runder Rand. Ein Mondzyklus dauert 29,5 Tage, etwas länger als ein Umlauf, weil die Erde inzwischen ein Stück um die Sonne weitergezogen ist.", "The Earth's shadow only touches the Moon during a lunar eclipse, and that only happens at full moon. The crescent of a lunar phase always bulges towards the Sun, whereas the Earth's shadow has a round edge. A lunar cycle lasts 29.5 days, a little longer than one orbit, because the Earth has moved some way round the Sun in the meantime."),
        ),
        lab("phy.finsternis", Topic.Astro, M, 0.55f) {
            val dS = 1.392e6; val dist = 1.496e8; val dM = 3474.0; val dd = dM * dist / dS
            task(
                question = l("Die Sonne hat 1,392 Millionen km Durchmesser und ist 149,6 Millionen km entfernt. Der Mond hat 3474 km Durchmesser. In welchem Abstand von uns sieht der Mond genau so groß aus wie die Sonne?", "The Sun has a diameter of 1.392 million km and is 149.6 million km away. The Moon has a diameter of 3474 km. At what distance from us does the Moon look exactly as large as the Sun?"),
                steps = listOf(num(l("Abstand in km", "Distance in km"), dd, "km", rel = 0.02, done = """§\approx ${m(dd, 0)}\ \text{km}§""",
                    hints = listOf(l("Kernidee: Gleich groß am Himmel heißt: gleiches Verhältnis von Durchmesser zu Entfernung (Strahlensatz).", "Key idea: the same size in the sky means the same ratio of diameter to distance (similar triangles)."), """§\dfrac{d_M}{r_M} = \dfrac{d_S}{r_S}§"""))),
                solution = listOf("""§r_M = 3474 \cdot \dfrac{1{,}496 \cdot 10^8}{1{,}392 \cdot 10^6}\ \text{km} \approx ${m(dd, 0)}\ \text{km}§"""),
